import { InvalidStateError, ValidationError, type ValidationIssue } from "./errors.js";
import { isMinorUnits, isSupportedCurrency, money, multiply, sum } from "./money.js";

export const CHANNELS = ["web", "store", "marketplace"] as const;
export type Channel = (typeof CHANNELS)[number];

export type OrderStatus = "placed" | "cancelled";

export interface OrderLine {
  readonly sku: string;
  readonly name: string;
  readonly qty: number;
  readonly unitPriceCents: number;
}

export interface Order {
  readonly id: string;
  readonly customerId: string;
  /** Legacy: kept on the order for receipts until the customer profile lookup exists. */
  readonly customerEmail: string;
  readonly lines: readonly OrderLine[];
  readonly status: OrderStatus;
  readonly channel: Channel;
  readonly currency: string;
  /** ISO-8601 instant. */
  readonly placedAt: string;
  /** ISO-8601 instant, set when the order is cancelled. */
  readonly cancelledAt?: string;
}

/** What a caller supplies to place an order; identity and timestamps come from the service. */
export interface NewOrder {
  readonly customerId: string;
  readonly customerEmail: string;
  readonly channel: Channel;
  readonly currency: string;
  readonly lines: readonly OrderLine[];
}

export const LIMITS = {
  maxLines: 100,
  maxQtyPerLine: 1000,
  maxSkuLength: 64,
  maxNameLength: 200,
  maxIdLength: 100,
  maxEmailLength: 254,
  /** Upper bound of an order total in minor units; protects against absurd inputs. */
  maxTotalMinor: 100_000_000,
} as const;

const SKU_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]*$/;
const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/**
 * Builds a placed order after checking every invariant:
 * at least one line, positive integer quantities, prices as integer minor units,
 * a supported currency and a bounded total. All problems are reported together.
 */
export function createOrder(input: NewOrder, meta: { id: string; placedAt: string }): Order {
  const issues = collectIssues(input);
  if (issues.length > 0) {
    throw new ValidationError(issues);
  }
  return {
    id: meta.id,
    customerId: input.customerId,
    customerEmail: input.customerEmail,
    lines: input.lines.map((line) => ({
      sku: line.sku,
      name: line.name,
      qty: line.qty,
      unitPriceCents: line.unitPriceCents,
    })),
    status: "placed",
    channel: input.channel,
    currency: input.currency,
    placedAt: meta.placedAt,
  };
}

/** Orders can be cancelled this long after they were placed. */
export const CANCELLATION_WINDOW_DAYS = 30;

const DAY_MS = 24 * 60 * 60 * 1000;

export function canCancel(order: Order, at: string): boolean {
  if (order.status !== "placed") {
    return false;
  }
  const elapsed = Date.parse(at) - Date.parse(order.placedAt);
  return elapsed <= CANCELLATION_WINDOW_DAYS * DAY_MS;
}

export function cancel(order: Order, cancelledAt: string): Order {
  if (!canCancel(order, cancelledAt)) {
    const reason = order.status === "placed" ? "cancelled after the cancellation window" : "cancelled";
    throw new InvalidStateError(order.id, order.status, reason);
  }
  return { ...order, status: "cancelled", cancelledAt };
}

/** Order total in minor units: the sum of qty x unit price over all lines. */
export function totalCents(order: Pick<Order, "lines" | "currency">): number {
  const lineTotals = order.lines.map((line) => multiply(money(line.unitPriceCents, order.currency), line.qty));
  return sum(lineTotals, order.currency).amountMinor;
}

function collectIssues(input: NewOrder): ValidationIssue[] {
  const issues: ValidationIssue[] = [];
  const fail = (path: string, message: string): void => {
    issues.push({ path, message });
  };

  if (!isNonBlank(input.customerId) || input.customerId.length > LIMITS.maxIdLength) {
    fail("customerId", `must be 1-${LIMITS.maxIdLength} characters`);
  }
  if (
    typeof input.customerEmail !== "string" ||
    input.customerEmail.length > LIMITS.maxEmailLength ||
    !EMAIL_PATTERN.test(input.customerEmail)
  ) {
    fail("customerEmail", "must be a valid email address");
  }
  if (!(CHANNELS as readonly unknown[]).includes(input.channel)) {
    fail("channel", `must be one of ${CHANNELS.join(", ")}`);
  }
  if (!isSupportedCurrency(input.currency)) {
    fail("currency", "must be a supported ISO-4217 currency code");
  }
  if (!Array.isArray(input.lines) || input.lines.length === 0) {
    fail("lines", "must contain at least one line");
    return issues;
  }
  if (input.lines.length > LIMITS.maxLines) {
    fail("lines", `must contain at most ${LIMITS.maxLines} lines`);
  }

  let runningTotal = 0;
  input.lines.forEach((line, index) => {
    const at = `lines[${index}]`;
    if (typeof line.sku !== "string" || line.sku.length > LIMITS.maxSkuLength || !SKU_PATTERN.test(line.sku)) {
      fail(`${at}.sku`, "must be an alphanumeric SKU of at most 64 characters");
    }
    if (!isNonBlank(line.name) || line.name.length > LIMITS.maxNameLength) {
      fail(`${at}.name`, `must be 1-${LIMITS.maxNameLength} characters`);
    }
    if (!Number.isInteger(line.qty) || line.qty < 1 || line.qty > LIMITS.maxQtyPerLine) {
      fail(`${at}.qty`, `must be an integer between 1 and ${LIMITS.maxQtyPerLine}`);
    }
    if (!isMinorUnits(line.unitPriceCents)) {
      fail(`${at}.unitPriceCents`, "must be a non-negative integer (minor units)");
      return;
    }
    if (Number.isInteger(line.qty) && line.qty > 0) {
      runningTotal += line.qty * line.unitPriceCents;
    }
  });
  if (runningTotal > LIMITS.maxTotalMinor) {
    fail("lines", `order total exceeds the maximum of ${LIMITS.maxTotalMinor} minor units`);
  }
  return issues;
}

function isNonBlank(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0;
}
import { totalCents, type Channel, type Order } from "./order.js";

export const ORDER_PLACED_TOPIC = "orders.placed";
export const ORDER_CANCELLED_TOPIC = "orders.cancelled";

/** Published when an order has been accepted and its payment authorized. */
export interface OrderPlaced {
  readonly type: "OrderPlaced";
  readonly schemaVersion: 3;
  readonly orderId: string;
  readonly customerId: string;
  /** Legacy field; a known ARCH-6 exception tracked in the PII baseline. */
  readonly customerEmail: string;
  /** ISO-8601 instant. */
  readonly placedAt: string;
  readonly channel: Channel;
  /** ISO-4217 code. */
  readonly currency: string;
  /** Integer, minor units. */
  readonly totalCents: number;
  readonly lines: ReadonlyArray<{
    readonly sku: string;
    readonly qty: number;
    readonly unitPriceCents: number;
  }>;
}

/** Published when a placed order is cancelled. */
export interface OrderCancelled {
  readonly type: "OrderCancelled";
  readonly schemaVersion: 1;
  readonly orderId: string;
  readonly customerId: string;
  /** ISO-8601 instant. */
  readonly cancelledAt: string;
  readonly reason?: string;
}

export type DomainEvent = OrderPlaced | OrderCancelled;

/** The single place where an `OrderPlaced` event is built. */
export function orderPlaced(order: Order): OrderPlaced {
  return {
    type: "OrderPlaced",
    schemaVersion: 3,
    orderId: order.id,
    customerId: order.customerId,
    customerEmail: order.customerEmail,
    placedAt: order.placedAt,
    channel: order.channel,
    currency: order.currency,
    totalCents: totalCents(order),
    lines: order.lines.map((line) => ({
      sku: line.sku,
      qty: line.qty,
      unitPriceCents: line.unitPriceCents,
    })),
  };
}

/** The single place where an `OrderCancelled` event is built. */
export function orderCancelled(order: Order, cancelledAt: string, reason?: string): OrderCancelled {
  return {
    type: "OrderCancelled",
    schemaVersion: 1,
    orderId: order.id,
    customerId: order.customerId,
    cancelledAt,
    ...(reason === undefined ? {} : { reason }),
  };
}

export function topicFor(event: DomainEvent): string {
  switch (event.type) {
    case "OrderPlaced":
      return ORDER_PLACED_TOPIC;
    case "OrderCancelled":
      return ORDER_CANCELLED_TOPIC;
  }
}

/** Partition key: all events of one order are ordered relative to each other. */
export function partitionKeyFor(event: DomainEvent): string {
  return event.orderId;
}
import { ValidationError, type ValidationIssue } from "../core/errors.js";
import type { Channel, NewOrder, OrderLine, OrderStatus } from "../core/order.js";
import type { CustomerOrdersQuery } from "../core/ports.js";
import { decodeCursor } from "./cursor.js";
import { InputReader, isJsonObject } from "./inputReader.js";

/**
 * Turns the untrusted body of `POST /orders` into a typed command.
 * Only the shape is checked here; the core enforces the business invariants.
 */
export function parsePlaceOrderRequest(body: unknown): NewOrder {
  if (!isJsonObject(body)) {
    throw new ValidationError([{ path: "body", message: "must be a JSON object" }]);
  }
  const reader = new InputReader(body);
  const customerId = reader.string("customerId");
  const customerEmail = reader.string("customerEmail");
  const channel = reader.string("channel");
  const currency = reader.string("currency");

  const lines: OrderLine[] = [];
  reader.array("lines").forEach((raw, index) => {
    const line = reader.object(`lines[${index}]`, raw);
    if (line === undefined) {
      return;
    }
    lines.push({
      sku: line.string("sku"),
      name: line.string("name"),
      qty: line.number("qty"),
      unitPriceCents: line.number("unitPriceCents"),
    });
    reader.issues.push(...line.issues);
  });

  if (reader.issues.length > 0) {
    throw new ValidationError(reader.issues);
  }
  // The core validates that `channel` is one of the supported values.
  return { customerId, customerEmail, channel: channel as Channel, currency, lines };
}

export interface CancelOrderRequest {
  readonly reason?: string;
}

/** The body of `POST /orders/{id}/cancel` is optional: `{ "reason"?: string }`. */
export function parseCancelRequest(body: unknown): CancelOrderRequest {
  if (body === undefined || body === null) {
    return {};
  }
  if (!isJsonObject(body)) {
    throw new ValidationError([{ path: "body", message: "must be a JSON object" }]);
  }
  const reader = new InputReader(body);
  const reason = reader.optionalString("reason");
  if (reason !== undefined && reason.length > 200) {
    reader.fail("reason", "must be at most 200 characters");
  }
  if (reader.issues.length > 0) {
    throw new ValidationError(reader.issues);
  }
  return reason === undefined ? {} : { reason };
}

const DEFAULT_LIST_LIMIT = 20;
const STATUSES: readonly string[] = ["placed", "cancelled"];

/** Query of `GET /orders?customerId=...[&status=placed|cancelled][&limit=1..100][&cursor=...]`. */
export function parseListOrdersQuery(params: URLSearchParams): CustomerOrdersQuery {
  const issues: ValidationIssue[] = [];
  const customerId = params.get("customerId") ?? "";
  if (customerId.trim() === "") {
    issues.push({ path: "customerId", message: "is required" });
  }
  const status = params.get("status");
  if (status !== null && !STATUSES.includes(status)) {
    issues.push({ path: "status", message: `must be one of ${STATUSES.join(", ")}` });
  }
  const rawLimit = params.get("limit");
  if (rawLimit !== null && !/^\d+$/.test(rawLimit)) {
    issues.push({ path: "limit", message: "must be a positive integer" });
  }
  if (issues.length > 0) {
    throw new ValidationError(issues);
  }
  const limit = rawLimit === null ? DEFAULT_LIST_LIMIT : Number(rawLimit);
  const cursor = params.get("cursor");
  return {
    customerId,
    limit,
    ...(status === null ? {} : { status: status as OrderStatus }),
    ...(cursor === null ? {} : { after: decodeCursor(cursor) }),
  };
}
import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { InvalidStateError, ValidationError } from "../src/core/errors.js";
import { canCancel, cancel, createOrder, totalCents, type NewOrder } from "../src/core/order.js";

const META = { id: "ord-1", placedAt: "2026-10-10T12:00:00.000Z" };

function newOrder(overrides: Partial<NewOrder> = {}): NewOrder {
  return {
    customerId: "cust-1",
    customerEmail: "jane@example.com",
    channel: "web",
    currency: "USD",
    lines: [{ sku: "SKU-1", name: "Desk lamp", qty: 2, unitPriceCents: 625 }],
    ...overrides,
  };
}

function issuePaths(fn: () => unknown): string[] {
  try {
    fn();
  } catch (error) {
    assert.ok(error instanceof ValidationError);
    return error.issues.map((issue) => issue.path);
  }
  assert.fail("expected a ValidationError");
}

describe("createOrder", () => {
  it("builds a placed order and computes the total in cents", () => {
    const order = createOrder(
      newOrder({
        lines: [
          { sku: "A", name: "Cable", qty: 3, unitPriceCents: 499 },
          { sku: "B", name: "Adapter", qty: 1, unitPriceCents: 1000 },
        ],
      }),
      META,
    );
    assert.equal(order.status, "placed");
    assert.equal(order.placedAt, META.placedAt);
    assert.equal(totalCents(order), 2497);
  });

  it("requires at least one line", () => {
    assert.deepEqual(issuePaths(() => createOrder(newOrder({ lines: [] }), META)), ["lines"]);
  });

  it("rejects non-positive and fractional quantities and non-integer prices", () => {
    const bad = newOrder({
      lines: [
        { sku: "A", name: "x", qty: 0, unitPriceCents: 100 },
        { sku: "B", name: "x", qty: 1.5, unitPriceCents: 100 },
        { sku: "C", name: "x", qty: 1, unitPriceCents: 9.99 },
      ],
    });
    assert.deepEqual(issuePaths(() => createOrder(bad, META)), [
      "lines[0].qty",
      "lines[1].qty",
      "lines[2].unitPriceCents",
    ]);
  });

  it("reports every problem at once", () => {
    const paths = issuePaths(() =>
      createOrder(newOrder({ customerId: " ", customerEmail: "nope", currency: "ZZZ", channel: "fax" as never }), META),
    );
    assert.deepEqual(paths, ["customerId", "customerEmail", "channel", "currency"]);
  });

  it("bounds the order total", () => {
    const huge = newOrder({ lines: [{ sku: "A", name: "x", qty: 1000, unitPriceCents: 999_999 }] });
    assert.deepEqual(issuePaths(() => createOrder(huge, META)), ["lines"]);
  });
});

describe("cancel", () => {
  it("moves a placed order to cancelled once", () => {
    const placed = createOrder(newOrder(), META);
    const cancelled = cancel(placed, "2026-10-11T08:00:00.000Z");
    assert.equal(cancelled.status, "cancelled");
    assert.equal(cancelled.cancelledAt, "2026-10-11T08:00:00.000Z");
    assert.equal(placed.status, "placed");
    assert.throws(() => cancel(cancelled, "2026-10-12T08:00:00.000Z"), InvalidStateError);
  });

  it("refuses to cancel after the cancellation window", () => {
    const placed = createOrder(newOrder(), META);
    assert.equal(canCancel(placed, "2026-11-09T12:00:00.000Z"), true);
    assert.throws(() => cancel(placed, "2026-11-10T12:00:01.000Z"), /cancellation window/);
  });
});
import assert from "node:assert/strict";
import { describe, it } from "node:test";
import type { OrderCancelled, OrderPlaced } from "../src/core/events.js";
import { FIXED_NOW, FakePayments, makeApp, placeOrderBody } from "./helpers.js";

describe("POST /orders", () => {
  it("places an order, answers 201 and publishes OrderPlaced v3", async () => {
    const { app, publisher, payments } = makeApp();
    const res = await app.handle("POST", "/orders", placeOrderBody());

    assert.equal(res.status, 201);
    assert.deepEqual(res.body, {
      id: "ord-1",
      status: "placed",
      placedAt: FIXED_NOW,
      currency: "USD",
      totalCents: 1250,
      lines: [{ sku: "SKU-1", name: "Desk lamp", qty: 2, unitPriceCents: 625 }],
    });
    assert.equal(publisher.events.length, 1);
    assert.deepEqual(publisher.events[0], {
      type: "OrderPlaced",
      schemaVersion: 3,
      orderId: "ord-1",
      customerId: "cust-1",
      customerEmail: "jane@example.com",
      placedAt: FIXED_NOW,
      channel: "web",
      currency: "USD",
      totalCents: 1250,
      lines: [{ sku: "SKU-1", qty: 2, unitPriceCents: 625 }],
    } satisfies OrderPlaced);
    assert.deepEqual(payments.requests, [
      { orderId: "ord-1", customerId: "cust-1", amountMinor: 1250, currency: "USD" },
    ]);
  });

  it("handles a multi-line order with a total of 2497 cents", async () => {
    const { app, publisher } = makeApp();
    const res = await app.handle(
      "POST",
      "/orders",
      placeOrderBody({
        lines: [
          { sku: "CAB-1", name: "Cable", qty: 3, unitPriceCents: 499 },
          { sku: "ADP-1", name: "Adapter", qty: 1, unitPriceCents: 1000 },
        ],
      }),
    );
    assert.equal(res.status, 201);
    assert.equal((publisher.events[0] as OrderPlaced).totalCents, 2497);
  });

  it("answers 400 with every issue for an invalid body and publishes nothing", async () => {
    const { app, publisher, payments } = makeApp();
    const res = await app.handle(
      "POST",
      "/orders",
      placeOrderBody({ currency: "ZZZ", lines: [{ sku: "SKU-1", name: "x", qty: 0, unitPriceCents: 100 }] }),
    );
    assert.equal(res.status, 400);
    const error = (res.body as { error: { code: string; details: Array<{ path: string }> } }).error;
    assert.equal(error.code, "validation_failed");
    assert.deepEqual(error.details.map((d) => d.path), ["currency", "lines[0].qty"]);
    assert.equal(publisher.events.length, 0);
    assert.equal(payments.requests.length, 0);
  });

  it("answers 400 for wrong types and a missing body", async () => {
    const { app } = makeApp();
    const wrongType = await app.handle("POST", "/orders", placeOrderBody({ customerId: 42, lines: "none" }));
    assert.equal(wrongType.status, 400);
    const missing = await app.handle("POST", "/orders", undefined);
    assert.equal(missing.status, 400);
  });

  it("answers 402 when the payment is declined and keeps nothing", async () => {
    const { app, publisher } = makeApp(new FakePayments({ authorized: false, declineReason: "card_expired" }));
    const res = await app.handle("POST", "/orders", placeOrderBody());
    assert.equal(res.status, 402);
    assert.equal(publisher.events.length, 0);
    assert.equal((await app.handle("GET", "/orders/ord-1")).status, 404);
  });
});

describe("GET /orders/{id}", () => {
  it("returns the stored order", async () => {
    const { app } = makeApp();
    await app.handle("POST", "/orders", placeOrderBody());
    const res = await app.handle("GET", "/orders/ord-1");
    assert.equal(res.status, 200);
    assert.deepEqual(Object.keys(res.body as object), ["id", "status", "placedAt", "currency", "totalCents", "lines"]);
  });

  it("answers 404 for an unknown order", async () => {
    const { app } = makeApp();
    const res = await app.handle("GET", "/orders/nope");
    assert.equal(res.status, 404);
    assert.equal((res.body as { error: { code: string } }).error.code, "order_not_found");
  });
});

describe("POST /orders/{id}/cancel", () => {
  it("cancels a placed order and publishes OrderCancelled", async () => {
    const { app, publisher, clock } = makeApp();
    await app.handle(
      "POST",
      "/orders",
      placeOrderBody({
        channel: "marketplace",
        currency: "EUR",
        lines: [{ sku: "EU-1", name: "Mug", qty: 1, unitPriceCents: 1990 }],
      }),
    );
    clock.advance(60_000);
    const res = await app.handle("POST", "/orders/ord-1/cancel", { reason: "customer request" });

    assert.equal(res.status, 200);
    assert.equal((res.body as { status: string }).status, "cancelled");
    assert.deepEqual(publisher.events[1], {
      type: "OrderCancelled",
      schemaVersion: 1,
      orderId: "ord-1",
      customerId: "cust-1",
      cancelledAt: "2026-10-10T12:01:00.000Z",
      reason: "customer request",
    } satisfies OrderCancelled);
  });

  it("answers 409 when the order is already cancelled and 404 when it does not exist", async () => {
    const { app, publisher } = makeApp();
    await app.handle("POST", "/orders", placeOrderBody());
    assert.equal((await app.handle("POST", "/orders/ord-1/cancel")).status, 200);
    assert.equal((await app.handle("POST", "/orders/ord-1/cancel")).status, 409);
    assert.equal((await app.handle("POST", "/orders/ord-9/cancel")).status, 404);
    assert.equal(publisher.events.length, 2);
  });

  it("rejects a malformed body", async () => {
    const { app } = makeApp();
    await app.handle("POST", "/orders", placeOrderBody());
    assert.equal((await app.handle("POST", "/orders/ord-1/cancel", { reason: 5 })).status, 400);
  });
});

describe("GET /orders", () => {
  it("lists a customer's orders newest first and filters by status", async () => {
    const { app, clock } = makeApp();
    await app.handle("POST", "/orders", placeOrderBody());
    clock.advance(1000);
    await app.handle("POST", "/orders", placeOrderBody());
    clock.advance(1000);
    await app.handle("POST", "/orders", placeOrderBody({ customerId: "cust-2" }));
    await app.handle("POST", "/orders/ord-1/cancel");

    const all = await app.handle("GET", "/orders?customerId=cust-1");
    assert.equal(all.status, 200);
    const ids = (all.body as { orders: Array<{ id: string }> }).orders.map((o) => o.id);
    assert.deepEqual(ids, ["ord-2", "ord-1"]);

    const placed = await app.handle("GET", "/orders?customerId=cust-1&status=placed&limit=5");
    assert.deepEqual((placed.body as { orders: Array<{ id: string }> }).orders.map((o) => o.id), ["ord-2"]);
  });

  it("pages with an opaque cursor", async () => {
    const { app, clock } = makeApp();
    for (let i = 0; i < 3; i += 1) {
      await app.handle("POST", "/orders", placeOrderBody());
      clock.advance(1000);
    }
    type Page = { orders: Array<{ id: string }>; nextCursor?: string };
    const first = (await app.handle("GET", "/orders?customerId=cust-1&limit=2")).body as Page;
    assert.deepEqual(first.orders.map((o) => o.id), ["ord-3", "ord-2"]);
    assert.ok(first.nextCursor);
    const second = (await app.handle("GET", `/orders?customerId=cust-1&limit=2&cursor=${first.nextCursor}`)).body as Page;
    assert.deepEqual(second.orders.map((o) => o.id), ["ord-1"]);
    assert.equal(second.nextCursor, undefined);
    assert.equal((await app.handle("GET", "/orders?customerId=cust-1&cursor=garbage")).status, 400);
  });

  it("rejects a missing customer, an unknown status and a bad limit", async () => {
    const { app } = makeApp();
    assert.equal((await app.handle("GET", "/orders")).status, 400);
    assert.equal((await app.handle("GET", "/orders?customerId=c&status=lost")).status, 400);
    assert.equal((await app.handle("GET", "/orders?customerId=c&limit=abc")).status, 400);
    assert.equal((await app.handle("GET", "/orders?customerId=c&limit=500")).status, 400);
  });
});

describe("routing", () => {
  it("answers the liveness probe", async () => {
    const { app } = makeApp();
    assert.deepEqual(await app.handle("GET", "/health"), { status: 200, body: { status: "ok" } });
  });

  it("answers 405 for a known path with the wrong method and 404 for unknown paths", async () => {
    const { app } = makeApp();
    assert.equal((await app.handle("DELETE", "/orders/ord-1")).status, 405);
    assert.equal((await app.handle("DELETE", "/orders")).status, 405);
    assert.equal((await app.handle("GET", "/carts/1")).status, 404);
    assert.equal((await app.handle("GET", "/orders/ord-1/refund")).status, 404);
  });

  it("ignores query strings and trailing slashes", async () => {
    const { app } = makeApp();
    await app.handle("POST", "/orders", placeOrderBody());
